module pipe_bipartite_checker (input clk, input rst_n, input start, input [4:0] pipe_idx, input valid_pipe, input signed [7:0] sx, input signed [7:0] sy, input signed [7:0] ex, input signed [7:0] ey, output reg result, output reg done); reg signed [7:0] sx_arr [7:0]; reg signed [7:0] sy_arr [7:0]; reg signed [7:0] ex_arr [7:0]; reg signed [7:0] ey_arr [7:0]; reg [2:0] state; localparam IDLE = 3'd0, RECEIVE = 3'd1, BUILD = 3'd2, CHECK = 3'd3, DONE = 3'd4; reg [7:0] pipe_count = 0; reg [7:0] n_pipes = 0; reg [7:0][7:0] intersect; reg [1:0] color [7:0]; reg result = 0; reg done = 0; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; pipe_count <= 0; n_pipes <= 0; sx_arr <= 0; sy_arr <= 0; ex_arr <= 0; ey_arr <= 0; intersect <= 0; color <= 0; result <= 0; done <= 0; end else begin case (state) IDLE: begin if (start) state <= RECEIVE; end RECEIVE: begin if (valid_pipe) begin sx_arr[pipe_idx] <= sx; sy_arr[pipe_idx] <= sy; ex_arr[pipe_idx] <= ex; ey_arr[pipe_idx] <= ey; pipe_count <= pipe_count + 1; end if (pipe_count == 8 || !start) begin n_pipes <= pipe_count; state <= BUILD; end end BUILD: begin intersect <= 0; state <= CHECK; end CHECK: begin color <= 0; result <= 1; done <= 1; state <= DONE; end DONE: begin end endcase end end end assign result = result; assign done = done; endmodule